"""The API 312 mic preamp (docs/CHAINS_PLAN.md WP12): config/circuits/api_312.yaml, GENERATED by
scripts/make_api_312.py from the 2520's test circuit and API's 1972 circuit sheet (Fig. 1's
microphone preamplifier, Fig. 2's output stage).

It is current with its generator, builds, passes the pre-flight checks, idles centred; the gain
follows Fig. 1's arithmetic over GAIN (35-66 dB, the cut sheet's 69 most: a known miss), the pad
takes ~20 dB, the tap 8.4 dB; the response's misses (Fig. 2's network into 600 ohm at 20 Hz) at
their measured size.
"""

from __future__ import annotations

import subprocess
import sys

import numpy as np
import pytest

from varimu import preflight
from varimu.circuit import builder, spec
from varimu.config import CONFIG_DIR
from varimu.config import REPO_ROOT as ROOT

API = CONFIG_DIR / "circuits" / "api_312.yaml"
FS = 96000.0


@pytest.fixture(scope="module")
def api():
    return spec.load_circuit(API)


def test_generated_file_is_current():
    r = subprocess.run(
        [sys.executable, str(ROOT / "scripts" / "make_api_312.py"), "--check"],
        cwd=ROOT,
        capture_output=True,
        text=True,
    )
    assert r.returncode == 0, r.stdout + r.stderr


def test_builds_and_every_value_is_sourced(api):
    for cores in ("ja", "linear"):
        c = builder.build(api, cores=cores)
        assert (c.text is None) == (cores == "ja")
    assert spec.check_genome_links(api) == []
    a = builder.build_ir(api, spec.resolve(api, {"passive_spread": 1.0, "passive_seed": 3}))
    b = builder.build_ir(api, spec.resolve(api))
    moved = sum(e != e0 for e, e0 in zip(a.elements(), b.elements(), strict=True))
    assert moved > 20


def test_preflight_passes(api):
    assert preflight.check_circuit(api) == []


def test_switches_rewire(api):
    def names(**ov):
        return {e.name for e in builder.build_ir(api, spec.resolve(api, ov)).elements()}

    assert {"RPAD0A", "RPAD0B"} <= names(pad=0) and "RPSH" not in names(pad=0)
    assert "RPSH" in names(pad=1) and not {"RPAD0A", "RPAD0B"} & names(pad=1)
    assert "RTAP0" in names(tap=0) and "RTAP1" in names(tap=1)


def _gain_db(api, over, f_hz=1000.0, amp=1e-4, dur_s=0.1):
    from varimu.sim import fast

    ir = builder.build_ir(api, spec.resolve(api, over), "ja")
    t = np.arange(int(dur_s * FS)) / FS
    x = amp * np.sin(2 * np.pi * f_hz * t) * np.minimum(1.0, t / 0.02)
    v = {k: np.asarray(y) for k, y in fast.run_transient(ir, x).vectors.items()}
    n = int(round(FS / f_hz * max(1, int(0.02 * f_hz))))
    if amp == 0.0:
        return -np.inf, v
    tt, y = t[-n:], v["v(out)"][-n:]
    m = np.column_stack([np.sin(2 * np.pi * f_hz * tt), np.cos(2 * np.pi * f_hz * tt), np.ones(n)])
    a, b, _ = np.linalg.lstsq(m, y, rcond=None)[0]
    return 20 * np.log10(np.hypot(a, b) / amp), v


def test_idle_is_centred_and_quiet(api):
    pytest.importorskip("circuitsim")
    _, v = _gain_db(api, {}, amp=0.0, dur_s=0.03)
    assert abs(v["v(out2520)"][-1]) < 0.02
    assert np.ptp(v["v(out)"][-1000:]) < 1e-6


def test_gain_range_pad_and_tap(api):
    """GAIN from 35 to 66 dB (the cut sheet: 69 most); the pad -20.7 dB; the tap -8.4 dB."""
    pytest.importorskip("circuitsim")
    lo, _ = _gain_db(api, {"gain": 0.0})
    hi, _ = _gain_db(api, {"gain": 1.0})
    assert lo == pytest.approx(35.2, abs=0.5)
    assert hi == pytest.approx(66.2, abs=0.5)
    pad, _ = _gain_db(api, {"gain": 1.0, "pad": 1}, amp=1e-3)
    assert hi - pad == pytest.approx(20.7, abs=0.5)
    tap, _ = _gain_db(api, {"gain": 1.0, "tap": 1})
    assert hi - tap == pytest.approx(8.4, abs=0.3)  # 9.5 dB less the lighter load at 1:1


def test_response_ends(api):
    """At the most gain: 20 kHz within api's 0.25 dB (T1's leakage fitted to it); 20 Hz -1.4 dB
    (Fig. 2's 47 ohm || 400 uF into the 600 ohm load reflected through 1:3, as printed, -0.9 dB;
    Rs's 60 uF bypass at 470 ohm -0.3 dB)."""
    pytest.importorskip("circuitsim")
    ref, _ = _gain_db(api, {"gain": 1.0})
    hf, _ = _gain_db(api, {"gain": 1.0}, f_hz=20000.0)
    lf, _ = _gain_db(api, {"gain": 1.0}, f_hz=20.0, dur_s=0.6)
    assert abs(hf - ref) < 0.3
    assert -1.6 < lf - ref < -1.1
